<script setup lang="ts">
import { ref, watch, onBeforeUnmount } from 'vue'
import { request, latestRequest } from '../api'
import type { ImportResult, StockSearch } from '../types'
const props=defineProps<{csrf?:string;busy:boolean;active?:boolean}>()
const emit=defineEmits<{select:[codes:string[]]; imported:[]}>()
const searchWarning=ref(''),searchSource=ref('')
const q=ref(''),results=ref<StockSearch[]>([]),loading=ref(false),error=ref(''),templates=ref<{name:string;codes:string[]}[]>([])
const code=ref(''),text=ref(''),fileName=ref(''),validation=ref<ImportResult|null>(null),importBusy=ref(false),overwrite=ref(false),feedback=ref('')
const latest=latestRequest();let timer:ReturnType<typeof setTimeout>|undefined
async function search(){const id=latest.next();loading.value=true;try{const result=await request<{items:StockSearch[];warning?:string;source?:string}>(`/api/stocks/search?q=${encodeURIComponent(q.value)}`);if(latest.current(id)){results.value=result.items;searchWarning.value=result.warning??'';searchSource.value=result.source??'';error.value=''}}catch(e){if(latest.current(id))error.value=e instanceof Error?e.message:String(e)}finally{if(latest.current(id))loading.value=false}}
watch(q,()=>{clearTimeout(timer);timer=setTimeout(search,300)})
watch(()=>props.active,async active=>{if(!active)return;void search();if(!templates.value.length)try{templates.value=(await request<{items:{name:string;codes:string[]}[]}>('/api/stocks/templates')).items}catch(e){error.value=e instanceof Error?e.message:String(e)}},{immediate:true})
onBeforeUnmount(()=>{clearTimeout(timer);latest.invalidate()})
async function pick(event:Event){const file=(event.target as HTMLInputElement).files?.[0];validation.value=null;feedback.value='';text.value='';if(!file)return;if(file.size>1_000_000){feedback.value='CSV 文件不得超过 1 MB。';return}try{text.value=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());fileName.value=file.name;const match=file.name.match(/(\d{6})/);if(match)code.value=match[1]}catch{feedback.value='文件不是有效 UTF-8 文本，请将 CSV 另存为 UTF-8 后再导入。'}}
watch([text,code],()=>{validation.value=null})
async function validate(){if(importBusy.value||!props.csrf)return;importBusy.value=true;try{validation.value=await request<ImportResult>('/api/imports/validate',{code:code.value,text:text.value},props.csrf);feedback.value=validation.value.valid?'校验通过，确认后保存到独立私有数据目录。':'请修正以下数据错误后再导入。'}catch(e){feedback.value=e instanceof Error?e.message:String(e)}finally{importBusy.value=false}}
async function commit(){if(importBusy.value||!props.csrf||!validation.value?.valid)return;importBusy.value=true;try{validation.value=await request<ImportResult>('/api/imports/commit',{code:code.value,text:text.value,overwrite:overwrite.value},props.csrf);feedback.value='CSV 已保存。将股票加入观察列表并切换到 CSV 模式，或直接在策略回放中选择 CSV。';emit('imported')}catch(e){feedback.value=e instanceof Error?e.message:String(e)}finally{importBusy.value=false}}
</script>
<template><section class="panel block-panel"><div class="panel-heading"><div><h2>股票搜索与模板</h2><p>添加到上方待保存列表；元数据未核实不表示可以实际交易</p></div></div><div class="panel-body"><label class="search-label">代码或名称<input v-model="q" placeholder="例如 600036 / 招商" aria-label="搜索股票"></label><div class="template-buttons"><button v-for="item in templates" :key="item.name" class="button secondary" :disabled="busy" @click="emit('select',item.codes)">{{ item.name }} · {{ item.codes.length }} 只</button></div><div v-if="error" class="error-banner">{{ error }}</div><div v-if="searchWarning" class="notice">{{ searchWarning }}</div><p v-if="searchSource" class="muted">搜索来源：{{ searchSource }}</p><div class="table-wrap stock-search-table"><table><thead><tr><th>股票</th><th>板块 / 元数据</th><th>数据来源</th><th>模拟可用</th><th></th></tr></thead><tbody><tr v-for="stock in results" :key="stock.code"><td>{{ stock.name }}<span class="stock-code">{{ stock.code }} · {{ stock.exchange }}</span></td><td>{{ stock.board }}<span class="stock-code">{{ stock.metadata_verified?'信息已核实':'信息待核实' }}</span></td><td>{{ stock.source }}</td><td>{{ stock.demo_tradable?'支持合成演示':'真实/CSV 研究' }}</td><td><button class="cancel-order" :disabled="busy" @click="emit('select',[stock.code])">加入列表</button></td></tr><tr v-if="!results.length"><td colspan="5" class="empty">{{ loading?'正在搜索…':'暂无匹配结果。可在上方输入六位代码。' }}</td></tr></tbody></table></div><p class="form-help">每次搜索最多 30 条。列表支持最多 50 只，公开数据采集耗时会随数量增加。</p></div></section>
<section class="panel block-panel"><div class="panel-heading"><div><h2>本地 CSV 导入</h2><p>只保存至私有 imports 目录，不上传到 GitHub；休市日和异常价格会被拒绝</p></div><a class="button secondary" href="/api/imports/template" download="daily-template.csv">下载模板</a></div><form class="panel-body" @submit.prevent="validate"><fieldset :disabled="busy||importBusy||!csrf"><div class="form-row"><label>股票代码<input v-model="code" pattern="[0-9]{6}" maxlength="6" required placeholder="600036"></label><label>UTF-8 CSV（最大 1 MB）<input type="file" accept=".csv,text/csv" @change="pick"></label></div><p class="form-help">{{ fileName||'模板价格是格式示例，不是真实日线。选择文件后，先校验再保存。' }}</p><details><summary>查看或编辑 CSV 文本</summary><textarea v-model="text" rows="7" aria-label="CSV 文本"></textarea></details><label class="checkbox-label"><input v-model="overwrite" type="checkbox">允许覆盖这只股票之前导入的文件</label><div class="action-row"><button class="button secondary" type="submit" :disabled="!text.trim()">{{ importBusy?'处理中…':'校验 CSV' }}</button><button class="button primary" type="button" :disabled="!validation?.valid" @click="commit">保存已校验数据</button></div></fieldset><p class="inline-feedback" role="status">{{ feedback }}</p><template v-if="validation"><p>{{ validation.row_count }} 根日线 · {{ validation.first_date }} — {{ validation.last_date }} · {{ validation.adjustment }}</p><ul class="error-list"><li v-for="(item,i) in validation.errors" :key="i">第 {{ item.line??'—' }} 行 {{ item.field }}：{{ item.message }}</li></ul><ul><li v-for="item in validation.warnings" :key="item">{{ item }}</li></ul></template></form></section></template>
